def compute(vars):
    numerator = vars["v1"]
    denominator = vars["v2"]
    if denominator == 0:
        return None
    ratio = numerator / denominator
    value = ratio * 100
    return {
        "value": value,
        "trace": {
            "numerator": numerator,
            "denominator": denominator,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
